function appDialog(opts){const root=$('#modalRoot'),title=$('#modalTitle'),body=$('#modalBody'),ok=$('#modalConfirm'),cancel=$('#modalCancel');if(!root)return Promise.resolve(false);title.textContent=opts.title||'';if(opts.html)body.innerHTML=opts.html;else body.textContent=opts.body||'';ok.textContent=opts.confirmLabel||'OK';ok.className='btn'+(opts.danger?' danger':'');const showCancel=opts.cancelLabel!==null;cancel.classList.toggle('hidden',!showCancel);if(showCancel)cancel.textContent=opts.cancelLabel||'Cancel';root.classList.remove('hidden');root.setAttribute('aria-hidden','false');ok.focus();return new Promise(resolve=>{const finish=v=>{if(v&&opts.collect){v=opts.collect();if(v===null)return}root.classList.add('hidden');root.setAttribute('aria-hidden','true');root.removeEventListener('click',onClick);document.removeEventListener('keydown',onKey);resolve(v)};const onClick=e=>{if(e.target===ok)finish(true);else if(e.target===cancel||(e.target&&e.target.hasAttribute&&e.target.hasAttribute('data-modal-cancel')))finish(false)};const onKey=e=>{if(e.key==='Escape'&&showCancel)finish(false)};root.addEventListener('click',onClick);document.addEventListener('keydown',onKey)})}
async function setting(key,fallback=null){const r=await FuelDB.get('settings',key);return r&&r.value!==undefined?r.value:fallback}
