function mapOnlineProviderId(){const d=window.FuelLogOfflineTiles&&FuelLogOfflineTiles.defaultProvider||'opentopomap';return state.settings.mapOnlineProvider||d}
function mapProviderOptionsHtml(selected){const list=window.FuelLogOfflineTiles?FuelLogOfflineTiles.listProviders():[{id:'opentopomap',label:'Terrain (OpenTopoMap)'}];return list.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.label)}</option>`).join('')}
function syncMapProviderControl(){const sel=$('#mapOnlineProvider');if(!sel)return;const off=!navigator.onLine;sel.disabled=off;sel.title=off?'Offline — bundled terrain map only':'Map style while online'}
function activeVehicle(){return state.vehicles.find(v=>v.id===state.settings.activeVehicle)||state.vehicles[0]||null}
function vehicleFillups(id){return state.fillups.filter(f=>f.vehicleId===id).sort((a,b)=>new Date(a.date)-new Date(b.date))}
function logCurrencyCode(){const s=state.settings.defaultCurrency;if(s&&/^[A-Z]{3}$/.test(String(s)))return String(s).toUpperCase();return 'EUR'}
function lastOdometerReading(vehicleId,excludeId){const v=state.vehicles.filter(x=>x.id===vehicleId)[0],fs=vehicleFillups(vehicleId).filter(f=>excludeId?f.id!==excludeId:true);if(fs.length)return fs[fs.length-1].odometer;return v&&v.initialOdometer!=null?Number(v.initialOdometer):0}
function lastPricePerLitre(vehicleId,excludeId){const fs=vehicleFillups(vehicleId).filter(f=>excludeId?f.id!==excludeId:true);if(!fs.length)return '';const last=fs[fs.length-1],p=last.pricePerLitre!=null?last.pricePerLitre:(last.litres?last.totalCost/last.litres:null);return p!=null&&isFinite(p)&&p>0?p:''}
function fillPriceValue(f,vid){if(f.pricePerLitre!=null&&isFinite(f.pricePerLitre))return roundFillPrice(f.pricePerLitre);if(f.litres&&f.totalCost)return roundFillPrice(f.totalCost/f.litres);if(f.id)return '';const last=lastPricePerLitre(vid,f.id||'');return last!==''?roundFillPrice(last):''}
function roundFillPrice(p){if(p===''||p==null||!isFinite(p))return '';return (Math.round(+p*1000)/1000).toFixed(3)}
function fillTotalFromLitresPrice(litres,price){const p=roundFillPrice(price);if(!litres||!p)return '';return (+litres*+p).toFixed(2)}
function fillDatePad(n){return n<10?'0'+n:String(n)}
function fillDateDisplay(iso){if(!iso)return '';const d=new Date(iso);if(isNaN(d.getTime()))return '';return d.getFullYear()+'/'+fillDatePad(d.getMonth()+1)+'/'+fillDatePad(d.getDate())+' '+fillDatePad(d.getHours())+':'+fillDatePad(d.getMinutes())}
function parseFillDateInput(s){const m=String(s||'').trim().match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})$/);if(!m)return null;const d=new Date(+m[1],+m[2]-1,+m[3],+m[4],+m[5],0);return isNaN(d.getTime())?null:d.toISOString()}
function fillEditedDate(old,inputDisplay){if(old&&old.date&&fillDateDisplay(old.date)===String(inputDisplay).trim())return old.date;const iso=parseFillDateInput(inputDisplay);return iso||new Date().toISOString()}
function minOdometerBefore(vehicleId,dateInput,excludeId){const v=state.vehicles.filter(x=>x.id===vehicleId)[0],d=new Date(dateInput),fs=vehicleFillups(vehicleId).filter(f=>(!excludeId||f.id!==excludeId)&&new Date(f.date)<d);if(fs.length)return fs[fs.length-1].odometer;return v&&v.initialOdometer!=null?Number(v.initialOdometer):0}
function calcMetrics(v){const fs=vehicleFillups(v&&v.id);if(!fs.length)return{distance:0,litres:0,cost:0,avg:null,costKm:null,last:null};const distance=Math.max(0,fs[fs.length-1].odometer-fs[0].odometer),litres=fs.reduce((sum,f)=>sum+Number(f.litres||0),0),costs=FuelLogData.amountsByCurrency(fs,state.vehicles),cost=Object.keys(costs).length===1?costs[Object.keys(costs)[0]]:null,intervals=FuelLogData.intervals(fs).intervals,fullDistance=intervals.reduce((sum,x)=>sum+x.distance,0),fullLitres=intervals.reduce((sum,x)=>sum+x.litres,0);return{distance,litres,cost,costs,avg:fullDistance>0?fullLitres/fullDistance*100:null,costKm:distance>0&&cost!==null?cost/distance:null,last:fs[fs.length-1]}}
function consumptionSeries(vehicleId){return FuelLogData.intervals(vehicleFillups(vehicleId)).intervals.map(x=>({t:new Date(x.end.date).getTime(),y:x.consumption}))}
function priceSeries(vehicleId,currency){return vehicleFillups(vehicleId).filter(f=>!currency||recordCurrency(f)===currency).map(f=>({t:new Date(f.date).getTime(),y:Number(f.pricePerLitre!=null?f.pricePerLitre:f.totalCost/f.litres)})).filter(p=>isFinite(p.y)&&p.y>0)}
function sparklineSvg(points,opts){opts=opts||{};if(!points||points.length<2)return'';const w=320,h=160,pad=28;const xs=points.map(p=>p.t),ys=points.map(p=>p.y);const minX=Math.min.apply(null,xs),maxX=Math.max.apply(null,xs);const minY=Math.min.apply(null,ys),maxY=Math.max.apply(null,ys);const spanX=maxX-minX||1,spanY=maxY-minY||1;const coord=p=>({x:pad+(p.t-minX)/spanX*(w-2*pad),y:h-pad-(p.y-minY)/spanY*(h-2*pad)});const pts=points.map(coord);const line=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ');const area=line+' L'+pts[pts.length-1].x.toFixed(1)+','+(h-pad)+' L'+pts[0].x.toFixed(1)+','+(h-pad)+' Z';const cls=opts.accent?'chart chart-accent':'chart';const yLo=minY.toFixed(2),yHi=maxY.toFixed(2);const d0=dateLabel(new Date(minX).toISOString()),d1=dateLabel(new Date(maxX).toISOString());return `<svg class="${cls}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(opts.yLabel||'Chart')}"><path class="gridline" d="M${pad} ${pad} H${w-pad}"/><path class="gridline" d="M${pad} ${h-pad} H${w-pad}"/><path class="area" d="${area}"/><path class="line" d="${line}"/><text x="${pad}" y="14">${yHi}</text><text x="${pad}" y="${h-6}">${yLo}</text><text x="${pad}" y="${h-pad+14}">${esc(d0)}</text><text x="${w-pad}" y="${h-pad+14}" text-anchor="end">${esc(d1)}</text></svg>`}
function analysisCard(vehicleId){const cons=consumptionSeries(vehicleId),currencies=Array.from(new Set(vehicleFillups(vehicleId).map(recordCurrency))),consHtml=cons.length>=2?`<div class="chart-block"><h3>L/100 km</h3>${sparklineSvg(cons,{yLabel:'L/100 km'})}</div>`:`<div class="chart-block"><h3>L/100 km</h3><p class="muted">${cons.length===1?'One completed interval: '+num(cons[0].y,2)+' L/100 km.':'Need two suitable full-tank points for consumption.'}</p></div>`,priceHtml=currencies.map(c=>{const price=priceSeries(vehicleId,c);return `<div class="chart-block"><h3>${esc(c)}/L</h3>${price.length>=2?sparklineSvg(price,{accent:true,yLabel:c+'/L'}):'<p class="muted">Need two prices in this currency.</p>'}</div>`}).join('');return `<div class="card"><h2>Fill analysis</h2>${consHtml}${priceHtml}</div>`}
