function dashboard(){const v=activeVehicle();if(!v)return `<div class="empty">Add a vehicle in Settings to begin.</div>`;const m=calcMetrics(v),recent=state.fillups.filter(f=>f.vehicleId===v.id).slice(0,5);return `<div class="hero"><div class="hero-card"><h1>${esc(v.name)}</h1><p>${[v.make,v.model,v.registration].filter(Boolean).map(esc).join(' · ')}</p><div class="hero-metric">${m.avg?num(m.avg,2):'—'} <small>L/100 km average</small></div></div><div class="side-card"><div><div class="kicker">Latest fill-up</div><div class="big">${m.last?money(m.last.totalCost,recordCurrency(m.last)):'No entries'}</div><p class="muted">${m.last?`${num(m.last.litres,2)} L · ${dateLabel(m.last.date)}`:'Add your first fill-up.'}</p></div><button class="btn" data-route="add">+ Add fill-up</button></div></div><div class="grid"><div class="stat"><div class="label">Distance logged</div><div class="value">${num(m.distance,0)} km</div></div><div class="stat"><div class="label">Fuel logged</div><div class="value">${num(m.litres,1)} L</div></div><div class="stat"><div class="label">Total spend</div><div class="value">${currencyTotals(vehicleFillups(v.id))}</div></div><div class="stat"><div class="label">Logged spending / km</div><div class="value">${m.distance>0?currencyTotals(vehicleFillups(v.id),m.distance):'—'}</div></div></div>${analysisCard(v.id)}<div class="section-head"><h2>Recent fill-ups</h2><button class="btn secondary" data-route="history">View all</button></div>${recent.length?`<div class="list">${recent.map(fillRow).join('')}</div>`:`<div class="empty">No fill-ups yet.</div>`}`}
function fillForm(){const v=activeVehicle(),f=Object.assign({},state.editing||{},state.prefill||{});state.prefill=null;const vid=f.vehicleId||(v&&v.id),veh=state.vehicles.filter(x=>x.id===vid)[0]||v,cc=esc(logCurrencyCode()),fuelPick=f.fuelId||FuelLogFuels.guess(f.fuelType||(veh&&veh.fuelType)||'')||(veh&&veh.preferredFuel)||'';const now=new Date(),dateIso=f.date||new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString(),odoVal=f.odometer!=null?f.odometer:lastOdometerReading(vid,f.id||''),litresVal=f.litres!=null?f.litres:(f.id?'':promoFillLitres()),priceVal=fillPriceValue(f,vid),totalVal=fillTotalFromLitresPrice(litresVal,priceVal)||(f.totalCost!=null?f.totalCost:'');return `<div class="card form-card fill-form-compact"><form id="fillForm"><input type="hidden" name="stationId" value="${esc(f.stationId||'')}"><input type="hidden" name="country" value="${esc(f.country||'')}"><input type="hidden" name="currency" value="${cc}"><div class="form-grid fill-form-grid"><div class="fill-form-top"><div class="field field-nolabel"><select name="vehicleId" required aria-label="Vehicle">${state.vehicles.map(x=>`<option value="${x.id}" ${vid===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field field-nolabel"><input type="text" name="date" class="fill-date-input" value="${esc(fillDateDisplay(dateIso))}" required aria-label="Date and time" placeholder="yyyy/mm/dd hh:mm" autocomplete="off"></div></div><div class="fill-form-row fill-form-fuel-row"><div class="input-affix fill-litres-affix"><input type="number" step="any" min="0" inputmode="decimal" name="litres" value="${litresVal!==''&&litresVal!=null?litresVal:''}" required aria-label="Litres"><span class="affix">litres</span></div><div class="input-affix fill-odo-affix"><input type="number" step="any" min="0" inputmode="decimal" name="odometer" value="${odoVal!=null?odoVal:''}" required aria-label="Odometer"><span class="affix">km</span></div><div class="fill-inline-check"><input type="checkbox" name="fullTank" id="fillFullTank" ${f.fullTank!==false?'checked':''}><label for="fillFullTank">Full</label></div></div><div class="fill-form-row fill-form-price-row"><div class="field"><label>Price / litre</label><div class="input-affix"><input type="number" step="0.001" min="0" inputmode="decimal" name="pricePerLitre" value="${priceVal!==''?priceVal:''}" required><span class="affix fill-currency-suffix">${cc}</span></div></div><div class="field"><label>Total cost</label><div class="input-affix"><input type="text" name="totalCost" class="fill-total-readonly" value="${totalVal}" readonly tabindex="-1" aria-readonly="true"><span class="affix fill-currency-suffix">${cc}</span></div></div></div><div class="field full"><label>Station</label><div class="field-inline"><input name="station" value="${esc(f.station||'')}" placeholder="Optional"><button type="button" class="btn secondary" id="fillFindStation">Find</button></div></div><div class="field"><label>Fuel</label><select name="fuelId"><option value="">Not set</option>${FuelLogFuels.LIST.map(x=>`<option value="${x.id}" ${fuelPick===x.id?'selected':''}>${x.label}</option>`).join('')}</select></div>${importedDetails(f)}<div class="field full"><label>Notes</label><textarea name="notes" rows="2">${esc(f.notes||'')}</textarea></div></div><div class="form-actions fill-form-actions"><button type="button" class="btn ghost" data-route="history">Cancel</button><button class="btn">${f.id?'Update fill-up':'Save fill-up'}</button></div></form></div>`}
