function setPriceSheetSnap(snap){const sheet=$('#priceSheet'),handle=$('#priceSheetHandle');if(!sheet)return;const s=normalizePriceSheetSnap(snap);sheet.setAttribute('data-snap',s);if(handle)handle.setAttribute('aria-expanded',s!=='peek');state.settings.priceSheetSnap=s;setSetting('priceSheetSnap',s).catch(console.error);syncPriceMapSize()}
