function locate(){return new Promise((res,rej)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>res(p.coords),rej,{timeout:8000,maximumAge:300000}):rej(new Error('No geolocation')))}
async function centerMapOnUser(){ensureMap();try{state.userPos=await locate();const ll=updateUserMarker();priceMap.map.setView(ll,Math.max(priceMap.map.getZoom(),14))}catch(e){toast('Location unavailable. Check location permission.')}}
function reorderMapCornerControls(){const mapEl=$('#stationMap');if(!mapEl)return;const corner=mapEl.querySelector('.leaflet-top.leaflet-left');if(!corner)return;const prov=corner.querySelector('.map-provider-control'),zoom=corner.querySelector('.leaflet-control-zoom'),loc=corner.querySelector('.map-locate-control');if(prov)corner.insertBefore(prov,corner.firstChild);if(zoom&&prov)corner.insertBefore(zoom,prov.nextSibling);else if(zoom)corner.insertBefore(zoom,corner.firstChild);if(loc&&zoom)corner.insertBefore(loc,zoom.nextSibling);else if(loc&&prov)corner.insertBefore(loc,prov.nextSibling);else if(loc)corner.appendChild(loc)}
function ensureLocateControl(map){if(!map||priceMap.locateControl)return;const Locate=L.Control.extend({options:{position:'topleft'},onAdd(){const wrap=L.DomUtil.create('div','leaflet-control leaflet-bar map-locate-control'),btn=L.DomUtil.create('a','map-locate-btn',wrap);btn.href='#';btn.setAttribute('role','button');btn.title='Centre on my location';btn.setAttribute('aria-label','Centre on my location');btn.innerHTML='◎';L.DomEvent.on(btn,'click',L.DomEvent.stopPropagation);L.DomEvent.on(btn,'click',L.DomEvent.preventDefault);L.DomEvent.on(btn,'click',()=>{if(btn.classList.contains('leaflet-disabled'))return;btn.classList.add('leaflet-disabled');centerMapOnUser().then(()=>btn.classList.remove('leaflet-disabled'),()=>btn.classList.remove('leaflet-disabled'))});return wrap}});priceMap.locateControl=new Locate();map.addControl(priceMap.locateControl)}
function priceSearchCenter(){if(priceMap&&priceMap.map){const c=priceMap.map.getCenter();return{lat:c.lat,lon:c.lng}}const v=mapViewCenter();return{lat:v.lat,lon:v.lon}}
function mountMapCornerControls(){const mapEl=$('#stationMap');if(!mapEl||!priceMap)return;const corner=mapEl.querySelector('.leaflet-top.leaflet-left'),sel=$('#mapOnlineProvider');if(!corner||!sel)return;let prov=corner.querySelector('.map-provider-control');if(!prov){prov=document.createElement('div');prov.className='leaflet-control map-provider-control';corner.insertBefore(prov,corner.firstChild)}if(sel.parentElement!==prov)prov.appendChild(sel);reorderMapCornerControls()}
function addMapTiles(map,cc){let tileApi=null,tiles=null;try{if(window.FuelLogOfflineTiles){tileApi=FuelLogOfflineTiles.createLayer({countryCode:cc,onlineProviderId:mapOnlineProviderId()});tiles=tileApi.layer;tileApi.loadManifest().then(function(){if(tiles.redraw)tiles.redraw();syncPriceMapSize()}).catch(function(){})}}catch(err){console.warn('Offline tile layer failed',err);tileApi=null;tiles=null}if(!tiles){const url=FuelProviders.legacyIOS()?'https://{s}.tile.openstreetmap.de/{z}/{x}/{y}.png':FALLBACK_TILES;tiles=L.tileLayer(url,{maxZoom:FuelProviders.legacyIOS()?18:17,subdomains:'abc',attribution:FuelProviders.legacyIOS()?'&copy; OpenStreetMap contributors':FALLBACK_ATTR})}tiles.addTo(map);let warned=false;tiles.on('tileerror',function(e){console.warn('Tile failed',e&&e.tile&&e.tile.src);if(!warned){warned=true;if(!navigator.onLine)toast('Using offline map');else toast('Some map tiles could not be loaded.')}});return{tileApi,tiles}}
