function updateUserMarker(){if(!priceMap||!state.userPos)return null;const ll=[state.userPos.latitude,state.userPos.longitude];if(priceMap.userMarker)priceMap.userMarker.setLatLng(ll);else priceMap.userMarker=L.circleMarker(ll,{radius:8,color:'#fff',fillColor:'#2563eb',fillOpacity:1,weight:3}).bindPopup('Your location').addTo(priceMap.map);return ll}
function updateMap(){if(!priceMap)return;const layer=priceMap.layer;layer.clearLayers();priceMap.markers=[];if((state.priceMeta||{}).reference)return;const ss=state.priceResults||[],minP=minSortPrice(ss),bounds=[];ss.forEach((s,i)=>{if(!Number.isFinite(s.lat)||!Number.isFinite(s.lon))return;const mk=priceTierMarkerStyle(s,minP),m=L.circleMarker([s.lat,s.lon],{radius:7,color:mk.color,fillColor:mk.fillColor,fillOpacity:.92,weight:2}).bindPopup(popupHtml(s,i)).addTo(layer);priceMap.markers[i]=m;bounds.push([s.lat,s.lon])});const ull=updateUserMarker();if(ull)bounds.push(ull);if(!priceMap.fitted&&bounds.length&&state.route==='prices'){priceMap.map.fitBounds(L.latLngBounds(bounds).pad(0.15),{maxZoom:15});priceMap.fitted=true}}
function settingsPage(){const av=activeVehicle(),defCur=esc((state.settings.defaultCurrency||'').toString().toUpperCase());return `<div class="settings-grid"><div class="card"><div class="section-head"><h2>Vehicles</h2><button id="addVehicle" class="btn secondary">+ Vehicle</button></div><div id="vehicles">${state.vehicles.length?state.vehicles.map(v=>`<div class="vehicle-card"><div><strong>${esc(v.name)}</strong><div class="muted">${[v.make,v.model,v.registration,fuelLabel(v.preferredFuel,v.fuelType)].filter(Boolean).map(esc).join(' · ')}</div></div><div class="actions-inline"><button class="icon-btn" data-vehicle-active="${v.id}">${av&&av.id===v.id?'★':'☆'}</button><button class="icon-btn" data-vehicle-edit="${v.id}">✎</button><button class="icon-btn danger-link" data-vehicle-delete="${v.id}">×</button></div></div>`).join(''):`<div class="empty">Add your first vehicle.</div>`}</div></div><div class="card"><h2>Log defaults</h2><div class="field"><label>Default currency</label><input id="defaultCurrency" name="defaultCurrency" pattern="[A-Z]{3}" maxlength="3" value="${defCur}" placeholder="EUR"><p class="muted">Used for all fill-ups. Leave empty to use EUR (€).</p></div></div><div class="card"><div class="section-head"><h2>Brand promos</h2><button id="addPromo" class="btn secondary">+ Promo</button></div><div id="promos">${(state.promos||[]).length?state.promos.slice().sort((a,b)=>String(a.brand).localeCompare(String(b.brand))).map(promoRow).join(''):`<div class="empty">No promos yet.</div>`}</div><div class="field"><label>Typical fill (L) — used to compare per-fill discounts</label><input id="promoFillLitres" type="number" step="1" min="1" value="${promoFillLitres()}"></div><p class="muted">Promos match the station's brand exactly (accents and case ignored). Cumulative promos stack. An exclusive promo is compared with that stack, and stations are sorted by the better effective price.</p></div><div class="card"><h2>Backup & portability</h2><p class="muted">Full JSON backup is the safest format. Import also accepts Jerrycan backups, generic JSON, CSV, semicolon CSV, TSV and delimited TXT files.</p><div class="actions-stack"><button id="exportJson" class="btn">Export JSON backup</button><button id="exportCsv" class="btn secondary">Export fill-ups CSV</button><label class="btn ghost">Import data<input id="importData" type="file" hidden></label></div><p class="muted">Imports recognise common English and Portuguese headings such as date/data, odometer/quilometragem, litres/litros, cost/custo and station/posto. Decimal commas are supported.</p><p class="muted">Last backup: ${state.settings.lastBackup?dateLabel(state.settings.lastBackup):'never'}</p></div><div class="card"><h2>Feedback</h2><div class="switchline tight"><input type="checkbox" id="suggestEnabled" ${state.settings.suggestBtn===false?'':'checked'}><label for="suggestEnabled">Show the floating ✉ suggestion button (top right)</label></div><p class="muted">Opens your email app with a pre-addressed suggestion message that names the page you were on. Nothing is sent until you press send.</p></div></div><div class="section-head"><h2>Privacy</h2></div><div class="card"><p><strong>Your log stays on this device.</strong> Vehicles, fill-ups, notes and settings are stored in IndexedDB. FuelLog has no application database on the server.</p><p class="muted">Clearing browser/site storage can erase local records, so keep periodic JSON backups. On older iPhones, exporting a backup before clearing Safari data is especially important.</p></div>`}
function promoDesc(p){const bits=[p.country||'Any country',p.type==='fill'?'-'+euro(p.amount)+' per fill':'-'+euro3(p.amount)+'/L',p.fuelId?FuelLogFuels.label(p.fuelId):'any fuel',p.cumulative===false?'exclusive':'cumulative'];if(p.validUntil)bits.push((FuelLogPromos.active(p)?'until ':'expired ')+dateLabel(p.validUntil+'T00:00:00'));if(p.notes)bits.push(p.notes);return bits.map(esc).join(' · ')}
function promoRow(p){return `<div class="vehicle-card"><div><strong>${esc(p.brand)}</strong><div class="muted">${promoDesc(p)}</div></div><div class="actions-inline"><button class="icon-btn" data-promo-edit="${p.id}">✎</button><button class="icon-btn danger-link" data-promo-delete="${p.id}">×</button></div></div>`}
function promoDialog(p={}){return `<div class="card form-card"><form id="promoForm"><input type="hidden" name="id" value="${p.id||''}"><div class="form-grid"><div class="field"><label>Brand</label><input name="brand" required value="${esc(p.brand||'')}" placeholder="Galp"></div><div class="field"><label>Country</label><select name="country"><option value="">Any country</option>${FuelProviders.countries().map(c=>`<option value="${c.code}" ${p.country===c.code?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label>Discount type</label><select name="type"><option value="litre" ${p.type!=='fill'?'selected':''}>€ per litre off</option><option value="fill" ${p.type==='fill'?'selected':''}>€ per fill off</option></select></div><div class="field"><label>Amount (€)</label><input name="amount" type="number" step="0.001" min="0" required value="${p.amount!=null?p.amount:''}"></div><div class="field"><label>Fuel</label><select name="fuelId"><option value="">Any fuel</option>${FuelLogFuels.LIST.map(x=>`<option value="${x.id}" ${p.fuelId===x.id?'selected':''}>${x.label}</option>`).join('')}</select></div><div class="field"><label>Valid until</label><div class="field-inline"><input name="validUntil" type="date" value="${esc(p.validUntil||'')}"><button type="button" id="promoClearDate" class="btn ghost">Clear</button></div><p class="muted">Leave empty for no expiry.</p></div><div class="field full"><div class="switchline"><input type="checkbox" name="cumulative" id="promoCumulative" ${p.cumulative!==false?'checked':''}><label for="promoCumulative">Cumulative</label></div><p class="muted">Stacks with other cumulative promos. Turn off if this promo cannot be combined.</p></div><div class="field full"><label>Notes</label><input name="notes" value="${esc(p.notes||'')}" placeholder="Optional"></div></div><div class="form-actions"><button type="button" id="promoCancel" class="btn ghost">Cancel</button><button class="btn">Save promo</button></div></form></div>`}
function wirePromoForm(){const f=$('#promoForm');$('#promoCancel').onclick=()=>render();const clearDate=$('#promoClearDate');if(clearDate)clearDate.onclick=()=>{if(f.validUntil)f.validUntil.value=''};f.onsubmit=async e=>{e.preventDefault();const d=formObject(f),old=(state.promos||[]).find(x=>x.id===d.id)||{};await FuelDB.put('promos',{...old,id:d.id||uid(),brand:d.brand.trim(),country:d.country||'',type:d.type==='fill'?'fill':'litre',amount:+d.amount||0,fuelId:d.fuelId||'',validUntil:d.validUntil||'',notes:d.notes.trim(),active:true,cumulative:d.cumulative==='on',updatedAt:new Date().toISOString()});await refresh();render();toast('Promo saved')}}
function vehicleDialog(v={}){const fuelPick=v.preferredFuel||FuelLogFuels.guess(v.fuelType)||(v.id?'':'DIESEL_B7');return `<div class="card form-card"><form id="vehicleForm"><input type="hidden" name="id" value="${v.id||''}"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required value="${esc(v.name||'')}" placeholder="My car"></div><div class="field"><label>Registration</label><input name="registration" value="${esc(v.registration||'')}"></div><div class="field"><label>Make</label><input name="make" value="${esc(v.make||'')}"></div><div class="field"><label>Model</label><input name="model" value="${esc(v.model||'')}"></div><div class="field"><label>Preferred fuel</label><select name="preferredFuel"><option value="">Not set</option>${FuelLogFuels.LIST.map(x=>`<option value="${x.id}" ${fuelPick===x.id?'selected':''}>${x.label}</option>`).join('')}</select></div><div class="field"><label>Default currency</label><input name="currency" required pattern="[A-Z]{3}" maxlength="3" value="${esc(v.currency||'EUR')}"></div>${importedDetails(v)}<div class="field"><label>Initial odometer</label><input type="number" step="any" name="initialOdometer" value="${v.initialOdometer||''}"></div></div><div class="form-actions"><button type="button" id="vehicleCancel" class="btn ghost">Cancel</button><button class="btn">Save vehicle</button></div></form></div>`}
function render(){const app=$('#app');state.pageKicker=null;if(state.route==='dashboard')app.innerHTML=dashboard();if(state.route==='add')app.innerHTML=fillForm();if(state.route==='history')app.innerHTML=history();if(state.route==='prices'){app.innerHTML=prices();wirePrices()}if(state.route==='settings')app.innerHTML=settingsPage();syncPricesRoute();wireCommon();updateSuggestBtn();wireCardToggles();const title=pageTitle();const pk=$('#pageKicker');if(pk)pk.textContent=title;document.title='FuelLog'+(title?' · '+title:'')}
