function prepareJerrycanBatch(data,destination,replace){
  const vehicles=replace?[]:state.vehicles.slice(),old=!replace&&destination?vehicles.find(v=>v.id===destination):null;
  if(destination&&!replace&&!old)throw new Error('Destination vehicle no longer exists.');
  const v=old||Object.assign({},data.vehicle,{id:uid()});
  if(!old)vehicles.push(v);
  const seen=new Set(),keys=new Set();
  (replace?[]:state.fillups).filter(f=>f.vehicleId===v.id).forEach(f=>{if(f.source&&f.source.format==='jerrycan')seen.add(f.source.key);keys.add(FuelLogData.sourceKey(Object.assign({},f,{currency:recordCurrency(f)})))});
  const fills=[];let duplicates=0;
  data.fillups.forEach(f=>{const k=FuelLogData.sourceKey(f);if(seen.has(f.source.key)||keys.has(k)){duplicates++;return}seen.add(f.source.key);keys.add(k);fills.push(Object.assign({},f,{id:uid(),vehicleId:v.id,fuelType:f.fuelId?FuelLogFuels.label(f.fuelId):'',updatedAt:new Date().toISOString()}))});
  return {replace,vehicles:old?[]:[v],fillups:fills,settings:[{key:'activeVehicle',value:v.id}],duplicates};
}
