async function init(){await FuelDB.open();if(FuelProviders.legacyIOS())document.documentElement.classList.add('legacy-ios');await refresh();if(!state.vehicles.length){const first={id:uid(),name:'My car',registration:'',make:'',model:'',fuelType:'Diesel B7',preferredFuel:'DIESEL_B7',initialOdometer:0};await FuelDB.put('vehicles',first);await setSetting('activeVehicle',first.id);await refresh()}await migrateData();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(console.error);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredPrompt=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(!state.deferredPrompt)return;state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$('#installBtn').classList.add('hidden')};const status=()=>{$('#offlineBadge').textContent=navigator.onLine?'Online':'Offline ready';if(state.route==='prices')updatePriceOfflineUi()};window.addEventListener('online',status);window.addEventListener('offline',status);status();const onPricesResize=()=>{if(state.route==='prices'&&priceMap&&priceMap.map)setTimeout(()=>priceMap.map.invalidateSize(),250)};window.addEventListener('orientationchange',onPricesResize);window.addEventListener('resize',onPricesResize);$$('[data-route]',document).forEach(b=>b.onclick=()=>route(b.dataset.route))}
init().catch(e=>{$('#app').innerHTML=`<div class="empty">FuelLog could not start: ${esc(e.message)}</div>`;console.error(e)});
